    print("==",f)
    for i,line in enumerate(open(f),1):
        for m in re.finditer(r'\[[^\]]*\]\(([^)]+)\)',line):
            t=m.group(1)
            if t.startswith('http'): continue
            path,_,anchor=t.partition('#')
            p=os.path.normpath(os.path.join(base,path)) if path else f
            ok=os.path.exists(p)
